-- Table: hrm_advance_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_advance_detail (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    advance_id         BIGINT NOT NULL REFERENCES hrm_advance(id) ON DELETE CASCADE,
    line_number        INTEGER NOT NULL CHECK (line_number > 0),
    installment_number INTEGER NOT NULL CHECK (installment_number > 0),
    due_date           DATE NOT NULL,
    amount             NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
    paid_amount        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (paid_amount >= 0),
    status             VARCHAR(20) NOT NULL DEFAULT 'pending'
                       CHECK (status IN ('pending', 'paid', 'overdue', 'cancelled')),
    notes              TEXT,
    UNIQUE (advance_id, line_number),
    UNIQUE (advance_id, installment_number)
);
